fn is_valid_bitmap(inscription_info: &InscriptionInfo) -> bool {
  if inscription_info.inscription_number < 0 {
    return false;
  }
  if inscription_info.is_json {
    return false;
  }
  if !inscription_info
    .content_type_hex
    .to_lowercase()
    .starts_with("746578742f706c61696e")
  {
    return false;
  }

  true
}

def get_bitmap_number(content_hex):
  content = None
  try:
    content = codecs.decode(content_hex, "hex").decode('utf-8')
  except:
    pass
  if content is None: return None
  if not content.endswith('.bitmap'): return None
  content = content[:-len('.bitmap')]
  if len(content) == 0: return None
  for ch in content:
    if ord(ch) > ord('9') or ord(ch) < ord('0'):
      return None
  if ord(content[0]) == ord('0') and len(content) != 1: return None
  return int(content)

